DROP TABLE IF EXISTS `cashout_subkon_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cashout_subkon_detail` (
  `id_cashout_subkon_detail` int NOT NULL AUTO_INCREMENT,
  `id_cashout_subkon` int NOT NULL,
  `berita_acara` varchar(255) DEFAULT NULL,
  `persentase` int DEFAULT NULL,
  `nominal` double DEFAULT NULL,
  `tanggal_jatuh_tempo` date DEFAULT NULL,
  `status` smallint DEFAULT '0' COMMENT '0 submit produksi, 1 enter jatuh tempo keuangan, 2 entry spp produksi, 3 cair cek keuangan, 4 paid by produksi',
  `spp_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `spp_tgl` date DEFAULT NULL,
  `spp_add_by` int DEFAULT NULL,
  `spp_created_at` datetime DEFAULT NULL,
  `pengajuan_cair_tgl` date DEFAULT NULL,
  `pengajuan_cari_add_by` int DEFAULT NULL,
  `pengajuan_cari_tgl_rencana_cair` date DEFAULT NULL,
  `pengajuan_cair_created_at` datetime DEFAULT NULL,
  `cek_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `cek_tgl` date DEFAULT NULL,
  `cek_add_by` int DEFAULT NULL,
  `cek_created_at` datetime DEFAULT NULL,
  `is_paid` smallint DEFAULT NULL,
  `paid_by` int DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `keterangan` text,
  PRIMARY KEY (`id_cashout_subkon_detail`),
  KEY `idx_csd_subkon_status_paid_due` (`id_cashout_subkon`,`status`,`is_paid`,`tanggal_jatuh_tempo`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
