  `reference_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `reference_id` int unsigned DEFAULT NULL,
  `id_kavling` int unsigned DEFAULT NULL,
  `id_proyek` int unsigned DEFAULT NULL,
