  `new_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `legacy_table` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `legacy_id` int unsigned DEFAULT NULL,
  `add_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_history_log_legacy` (`legacy_table`,`legacy_id`),
