  KEY `reference_type_reference_id` (`reference_type`,`reference_id`),
  KEY `legacy_table_legacy_id` (`legacy_table`,`legacy_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
