DROP TABLE IF EXISTS `log_pembayaran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `log_pembayaran` (
  `id_pembayaran` int NOT NULL AUTO_INCREMENT,
  `id_mkdt` int DEFAULT NULL,
  `id_keuangan` varchar(255) DEFAULT NULL,
  `nominal` float DEFAULT NULL,
  `tanggal_bayar` date DEFAULT NULL,
  `payment_type` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `keterangan` text,
  `is_deleted` smallint DEFAULT '0',
  `st` varchar(10) DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `add_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `edit_by` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id_pembayaran`)
) ENGINE=InnoDB AUTO_INCREMENT=1051 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

