DROP TABLE IF EXISTS `log_pembayaran_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `log_pembayaran_detail` (
  `id_pembayaran_detail` int NOT NULL AUTO_INCREMENT,
  `id_pembayaran` int DEFAULT NULL,
  `id_keuangan_item_list` int DEFAULT NULL,
  `nominal` double DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `add_by` int DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `edit_by` int DEFAULT NULL,
  `booking_is_installment` tinyint DEFAULT '0',
  PRIMARY KEY (`id_pembayaran_detail`),
  KEY `fk_log_pembayaran_detail` (`id_pembayaran`),
  CONSTRAINT `fk_log_pembayaran_detail` FOREIGN KEY (`id_pembayaran`) REFERENCES `log_pembayaran` (`id_pembayaran`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1424 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
