DROP TABLE IF EXISTS `mkdt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mkdt` (
  `id_mkdt` int NOT NULL AUTO_INCREMENT,
  `id_konsumen` int DEFAULT NULL,
  `status_mkdt` varchar(255) DEFAULT NULL,
  `is_batal` int DEFAULT '0',
  `is_allin` smallint DEFAULT '0',
  `is_ajb` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `is_lunas` smallint DEFAULT '0',
  `dajam_selesai` int NOT NULL DEFAULT '0',
  `is_kpr` smallint DEFAULT '0',
  `is_subsidi` smallint DEFAULT '0',
  `is_sudah_isi_tagihan` smallint DEFAULT '0',
  `is_sudah_turun_kpr` smallint DEFAULT '0',
  `refund_paid` smallint DEFAULT '0',
  `booking_paid` smallint DEFAULT '0',
  `keterangan_batal` varchar(255) DEFAULT NULL,
  `perlu_refund` tinyint(1) DEFAULT '0',
  `surat_batal` varchar(255) DEFAULT NULL,
  `mkdt_batal_oleh` int DEFAULT NULL,
  `mkdt_batal_tgl` datetime DEFAULT NULL,
  `keuangan_batal_oleh` int DEFAULT NULL,
  `keuangan_batal_tgl` datetime DEFAULT NULL,
  `refund_keterangan` text,
  `refund` double DEFAULT NULL,
  `refund_tgl` date DEFAULT NULL,
  `status_kavling` varchar(12) DEFAULT NULL,
  `booking_fee` double DEFAULT '0',
  `booking_tgl` date DEFAULT NULL,
  `tgl_harga` date DEFAULT NULL,
  `id_hargajual` int DEFAULT NULL,
  `harga_allin` double DEFAULT '0',
  `harga_diskon_uang_muka` double DEFAULT '0',
  `harga_uang_muka` double DEFAULT '0',
  `harga_jual` double DEFAULT '0',
  `harga_jual_net` double DEFAULT '0',
  `harga_diskon_hargajual` double DEFAULT '0',
  `harga_administrasi` double DEFAULT '0',
  `harga_ppn` double DEFAULT '0',
  `harga_bphtb` double DEFAULT '0',
  `harga_biaya_proses` double DEFAULT '0',
  `harga_kpr` double DEFAULT '0',
  `harga_kpr_acc` double DEFAULT '0',
  `harga_penambahan_um` double DEFAULT '0',
  `harga_penambahan` double NOT NULL DEFAULT '0',
  `harga_penambahan_tanah` double DEFAULT '0',
  `harga_sbum` double DEFAULT '0',
  `keterangan_penambahan_biaya` text,
  `bank` varchar(25) DEFAULT NULL,
  `id_bank` int NOT NULL,
  `harga_total` double DEFAULT '0',
  `harga_harus_bayar` double NOT NULL DEFAULT '0',
  `perintah_bangun` smallint DEFAULT '0',
  `perintah_bangun_tgl` date DEFAULT NULL,
  `perintah_bangun_oleh` varchar(50) DEFAULT NULL,
  `perintah_bangun_file` varchar(255) DEFAULT NULL,
  `wawancara` smallint DEFAULT '0',
  `wawancara_tgl` date DEFAULT NULL,
  `sp3k` smallint DEFAULT '0',
  `sp3k_tgl` date DEFAULT NULL,
  `sp3k_tgl_exp` date DEFAULT NULL,
  `sp3k_no` varchar(255) DEFAULT NULL,
  `sp3k_file` varchar(255) DEFAULT NULL,
  `akad` smallint DEFAULT '0',
  `rencana_akad_tgl` date DEFAULT NULL,
  `akad_tgl` date DEFAULT NULL,
  `akad_indent` tinyint(1) DEFAULT '0',
  `notaris` varchar(255) DEFAULT NULL,
  `debitur_no` varchar(255) DEFAULT NULL,
  `bast_no` varchar(255) DEFAULT NULL,
  `bast_file` varchar(255) DEFAULT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `keterangan_status` text,
  `id_kavling` int DEFAULT NULL,
  `id_cair` smallint DEFAULT NULL,
  `jenis_subsidi` varchar(255) DEFAULT NULL,
  `rincian` text,
  `promo` varchar(255) DEFAULT NULL,
  `file_spptb` varchar(255) DEFAULT NULL,
  `file_surat_kuasa` varchar(255) DEFAULT NULL,
  `is_ganti_nama` enum('Normal','Ganti Nama','Pindah Kavling') DEFAULT 'Normal',
  `is_ganti_kavling` enum('Normal','Ganti Kavling') DEFAULT 'Normal',
  `uniq_id` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `keuangan_saved_by` varchar(255) DEFAULT NULL,
  `status_sikasep` smallint DEFAULT '0',
  `status_sikumbang` smallint DEFAULT '0',
  `add_by` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `edit_by` varchar(255) DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id_mkdt`),
  KEY `idx_mkdt_id_kavling` (`id_kavling`),
  KEY `idx_mkdt_id_konsumen` (`id_konsumen`),
  KEY `idx_mkdt_sp3k_urgent` (`sp3k_tgl_exp`,`akad_tgl`,`is_batal`),
  KEY `idx_mkdt_rencana_akad_urgent` (`rencana_akad_tgl`,`akad_tgl`,`is_batal`)
) ENGINE=InnoDB AUTO_INCREMENT=445 DEFAULT CHARSET=latin1;
