--
-- Table structure for table `notification_deliveries`
--

DROP TABLE IF EXISTS `notification_deliveries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_deliveries` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `notification_recipient_id` int unsigned NOT NULL,
  `notification_id` int NOT NULL,
  `user_id` int unsigned NOT NULL,
  `channel` enum('web_push','email') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('pending','processing','sent','failed','skipped','preference_blocked') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `available_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `claimed_at` datetime DEFAULT NULL,
  `claim_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `last_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_notif_delivery_recipient_channel` (`notification_recipient_id`,`channel`),
  KEY `idx_notif_delivery_queue` (`channel`,`status`,`available_at`,`id`),
  KEY `idx_notif_delivery_notif_user` (`notification_id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=37109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

