--
-- Table structure for table `notification_event_types`
--

DROP TABLE IF EXISTS `notification_event_types`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_event_types` (
  `event_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `label` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `default_in_app` tinyint unsigned NOT NULL DEFAULT '1',
  `default_email` tinyint unsigned NOT NULL DEFAULT '1',
  `default_web_push` tinyint unsigned NOT NULL DEFAULT '1',
  `is_mandatory` tinyint unsigned NOT NULL DEFAULT '0',
  `relevant_groups` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Semicolon-separated group IDs, NULL = all groups',
  `sort_order` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`event_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
