DROP TABLE IF EXISTS `notification_recipients`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_recipients` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `notification_id` int NOT NULL,
  `user_id` int unsigned NOT NULL,
  `in_app_visible` tinyint unsigned DEFAULT '1',
  `read_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_notif_recip_user` (`notification_id`,`user_id`),
  KEY `notification_id_user_id` (`notification_id`,`user_id`),
  KEY `idx_notif_recip_user_read` (`user_id`,`read_at`,`notification_id`),
  KEY `idx_notif_recip_user_visible_read` (`user_id`,`in_app_visible`,`read_at`,`notification_id`)
) ENGINE=InnoDB AUTO_INCREMENT=40070 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

