DROP TABLE IF EXISTS `pencairan_akad_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pencairan_akad_item` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `id_plan` int unsigned NOT NULL,
  `jenis` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'retensi|tenor',
  `id_list_dajam` int DEFAULT NULL,
  `urutan_tenor` int DEFAULT NULL,
  `nominal` decimal(15,2) NOT NULL DEFAULT '0.00',
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pencairan_akad_item_plan` (`id_plan`),
  KEY `idx_pencairan_akad_item_dajam` (`id_list_dajam`)
) ENGINE=InnoDB AUTO_INCREMENT=918 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
