--
-- Table structure for table `pencairan_akad_pengajuan`
--

DROP TABLE IF EXISTS `pencairan_akad_pengajuan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pencairan_akad_pengajuan` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `id_plan` int unsigned NOT NULL,
  `tanggal_pengajuan` date NOT NULL,
  `tanggal_rencana_cair` date DEFAULT NULL,
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `lampiran_surat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `total_pengajuan` decimal(15,2) NOT NULL DEFAULT '0.00',
  `total_cair` decimal(15,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT 'active|partial|paid|void',
  `void_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `add_by` int DEFAULT NULL,
  `edit_by` int DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pencairan_akad_pengajuan_plan` (`id_plan`),
  KEY `idx_pencairan_akad_pengajuan_status` (`status`),
  KEY `idx_pencairan_akad_pengajuan_rencana` (`tanggal_rencana_cair`)
) ENGINE=InnoDB AUTO_INCREMENT=882 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

